{"path": "task/workspace/cep.go", "start": 51, "lines": 48, "offset": 0, "total_lines": 98, "content": "type StreamSendEndpoint func(ctx context.Context, stream streaming.ClientStream, message interface{}) (err error)

// EqualsTo returns true if and only if both endpoints reference the same underlying function
func (e StreamSendEndpoint) EqualsTo(e2 StreamSendEndpoint) bool {
	// Compare function pointers
	return &e == &e2
}

// StreamSendMiddleware wraps a StreamSendEndpoint
type StreamSendMiddleware func(next StreamSendEndpoint) StreamSendEndpoint

// StreamSendMiddlewareBuilder builds a middleware with information from a context
type StreamSendMiddlewareBuilder func(ctx context.Context) StreamSendMiddleware

// StreamChain composes middlewares into one middleware (right-to-left composition)
func StreamChain(mws ...StreamMiddleware) StreamMiddleware {
	return func(next StreamEndpoint) StreamEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// StreamRecvChain composes recv middlewares into one middleware (right-to-left composition)
func StreamRecvChain(mws ...StreamRecvMiddleware) StreamRecvMiddleware {
	return func(next StreamRecvEndpoint) StreamRecvEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// StreamSendChain composes send middlewares into one middleware (right-to-left composition)
func StreamSendChain(mws ...StreamSendMiddleware) StreamSendMiddleware {
	return func(next StreamSendEndpoint) StreamSendEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// DummyDummyMiddleware is a dummy middleware that returns next unchanged
func DummyDummyMiddleware(next StreamEndpoint) StreamEndpoint {
	return next
}
