package cep

import "context"

// StreamEndpoint is the endpoint for client-side streaming RPC
type StreamEndpoint func(ctx context.Context, req, resp interface{}) error

// StreamMiddleware is middleware for client stream endpoint
type StreamMiddleware func(StreamEndpoint) StreamEndpoint

// StreamMiddlewareBuilder builds a middleware with information from a context
