// Package transport provides predefined transport protocol.
package transport

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0

	TTHeader  Protocol = 2
	Framed    Protocol = 4
	HTTP      Protocol = 8
	GRPC      Protocol = 16
	HESSIAN2  Protocol = 32
	STREAMING Protocol = 64

	TTHeaderFramed    = TTHeader | Framed
	TTHeaderStreaming = TTHeader | STREAMING
	GRPCStreaming     = GRPC | STREAMING
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	switch tp {
	case PurePayload:
		return "PurePayload"
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case STREAMING:
		return "STREAMING"
	case TTHeaderFramed:
		return "TTHeaderFramed"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	default:
		// Handle flag compositions
		var parts []string
		if tp&TTHeader != 0 {
			parts = append(parts, "TTHeader")
		}
		if tp&Framed != 0 {
			parts = append(parts, "Framed")
		}
		if tp&HTTP != 0 {
			parts = append(parts, "HTTP")
		}
		if tp&GRPC != 0 {
			parts = append(parts, "GRPC")
		}
		if tp&HESSIAN2 != 0 {
			parts = append(parts, "HESSIAN2")
		}
		if tp&STREAMING != 0 {
			parts = append(parts, "STREAMING")
		}
		if len(parts) > 0 {
			return parts[0] + "|" + joinParts(parts[1:])
		}
	}
	return Unknown
}

func joinParts(parts []string) string {
	if len(parts) == 0 {
		return ""
	}
	result := parts[0]
	for i := 1; i < len(parts); i++ {
		result += "|" + parts[i]
	}
	return result
}

// DefaultProtocol returns the default transport protocol.
func DefaultProtocol() Protocol {
	return Framed
}
